# Dark-spot candidates: K dB or more below the mean of the sea pixels in an N x N map-pixel window.
N, K = 31, 3.0
FLAG = -200  # flagged pixels are shifted by FLAG dB, into their own colour class (orange)
FLAG_COLORMAP = [[[-300, -150], [255, 100, 0, 255]]] + DB_COLORMAP
BOX = dict(kernel=[[1] * N] * N, factor=1.0 / (N * N), border="replicate", replace_invalid=0)


def dark_spot_layer(start, end, name):
    db = one_pass(start, end).apply(lambda x: x.log(10) * 10)
    sea = db.process("mask_polygon", data=db, mask=LAND, inside=True)
    # Mean over sea pixels only: window sum of sea dB / window count of sea pixels (no data counts 0).
    total = sea.apply_kernel(**BOX)
    count = sea.apply(lambda x: x * 0 + 1).apply_kernel(**BOX)
    background = total.merge_cubes(count, overlap_resolver=lambda x, y: x / y)
    anomaly = sea.merge_cubes(background, overlap_resolver=lambda x, y: x - y)
    # The threshold runs in apply(), not in an overlap_resolver: at c9b6ee3, merge_cubes passes x and y
    # to its resolver as keyword arguments that also replace any literal argument named x or y inside it.
    shift = anomaly.apply(lambda a: (a < -K) * FLAG)
    flagged = sea.merge_cubes(shift, overlap_resolver=lambda x, y: x + y)
    colored = flagged.process("colormap", data=flagged, colormap=FLAG_COLORMAP)
    add_graph_to_map(colored.save_result("PNG"), name)


# Sentinel-2 red reflectance, 0 black to 0.005 white in 20 steps; below 0 black, above white.
R_LO, R_HI, R_STEPS = 0.0, 0.005, 20
R_STEP = (R_HI - R_LO) / R_STEPS
RED_COLORMAP = (
    [[[-1, R_LO], [0, 0, 0, 255]]]
    + [
        [[R_LO + i * R_STEP, R_LO + (i + 1) * R_STEP], [round(255 * (i + 0.5) / R_STEPS)] * 3 + [255]]
        for i in range(R_STEPS)
    ]
    + [[[R_HI, 2], [255, 255, 255, 255]]]
)


def optical_layer(start, end, mgrs_tile, name):
    """Sentinel-2 L2A band B04 of one MGRS tile between start and end (UTC)."""
    cube = DataCube(
        graph=PGNode(
            "load_collection",
            id="sentinel-2-l2a",
            spatial_extent=bounding_box,
            temporal_extent=[start, end],
            bands=["B04"],
            properties={"s2:mgrs_tile": condition("eq", mgrs_tile)},
        )
    )
    cube = cube.process("apply_pixel_selection", pixel_selection="first", data=cube)
    colored = cube.process("colormap", data=cube, colormap=RED_COLORMAP)
    add_graph_to_map(colored.save_result("PNG"), name)


